mapper.select:
SELECT h.*, p.slug AS post_slug, p.title FROM user_post_reading_history h JOIN post p ON p.id = h.post_id WHERE h.user_id = #{userId} AND p.status = 'PUBLISHED'
AND (h.last_read_at < #{cursorTime} OR (h.last_read_at = #{cursorTime} AND h.post_id < #{cursorPostId}))
ORDER BY h.last_read_at DESC, h.post_id DESC LIMIT #{limit}
